import React from "react";
import "./MapComponent.css";

// Simplified schematic campus layout — percentage coordinates within the
// canvas. No external mapping API, per project scope (see README notes).
const POSITIONS = {
  lib: { x: 22, y: 30 },
  "hall-a": { x: 45, y: 20 },
  "hall-b": { x: 58, y: 22 },
  admin: { x: 72, y: 34 },
  cafeteria: { x: 35, y: 55 },
  residence: { x: 78, y: 60 },
  gym: { x: 55, y: 68 },
  "study-centre": { x: 20, y: 62 },
};

export default function MapComponent({ locations, selectedId, onSelect }) {
  return (
    <div className="map-canvas">
      {locations.map((loc) => {
        const pos = POSITIONS[loc.id] || { x: 50, y: 50 };
        const active = loc.id === selectedId;
        return (
          <button
            key={loc.id}
            className={`map-pin ${active ? "active" : ""}`}
            style={{ left: `${pos.x}%`, top: `${pos.y}%` }}
            onClick={() => onSelect(loc.id)}
            title={loc.name}
          >
            <span className="map-pin-dot"><span>📍</span></span>
            <span className="map-pin-label">{loc.name}</span>
          </button>
        );
      })}
    </div>
  );
}
